### 3. Create HttpClient-based implementation in Client project

Create `ShipmentTracker.Client/Services/ShipmentService.cs`:
```csharp
using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public class ShipmentService : IShipmentService
{
    private readonly HttpClient _http;

    public ShipmentService(HttpClient http) => _http = http;

    public async Task<List<Shipment>> GetAllShipmentsAsync() =>
        await _http.GetFromJsonAsync<List<Shipment>>("api/shipments") ?? [];

    public async Task<List<Shipment>> GetShipmentsByStatusAsync(ShipmentStatus? status)
    {
        var url = status.HasValue ? $"api/shipments?status={status}" : "api/shipments";
        return await _http.GetFromJsonAsync<List<Shipment>>(url) ?? [];
    }

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber) =>
        await _http.GetFromJsonAsync<Shipment?>($"api/shipments/track/{trackingNumber}");

    public async Task UpdateShipmentStatusAsync(int id, ShipmentStatus newStatus) =>
        await _http.PutAsJsonAsync($"api/shipments/{id}/status", newStatus);
}
```

