    };

    private static readonly Lock _lock = new();

    public Task<List<Shipment>> GetAllShipmentsAsync() =>
        Task.FromResult(_shipments.ToList());

    public Task<List<Shipment>> GetShipmentsByStatusAsync(ShipmentStatus? status)
    {
        var result = status.HasValue
            ? _shipments.Where(s => s.Status == status.Value).ToList()
            : _shipments.ToList();
        return Task.FromResult(result);
    }

    public Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber) =>
        Task.FromResult(_shipments.FirstOrDefault(s =>
            s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase)));

    public Task UpdateShipmentStatusAsync(int id, ShipmentStatus newStatus)
    {
        lock (_lock)
        {
            var shipment = _shipments.FirstOrDefault(s => s.Id == id);
            if (shipment is not null)
            {
                shipment.Status = newStatus;
                if (newStatus == ShipmentStatus.Delivered)
                    shipment.ActualDelivery = DateTime.UtcNow;
            }
        }
        return Task.CompletedTask;
    }
}
